package com.cartalaap.garage;import java.util.List;import org.springframework.http.HttpStatus;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.DeleteMapping;import org.springframework.web.bind.annotation.GetMapping;import org.springframework.web.bind.annotation.PatchMapping;import org.springframework.web.bind.annotation.PathVariable;import org.springframework.web.bind.annotation.PostMapping;import org.springframework.web.bind.annotation.RequestBody;import org.springframework.web.bind.annotation.RequestMapping;import org.springframework.web.bind.annotation.ResponseStatus;import org.springframework.web.bind.annotation.RestController;import jakarta.validation.Valid;
@RestController@RequestMapping("/api/garage")public class GarageController{private final GarageService service;public GarageController(GarageService service){this.service=service;}@GetMapping("/users/{username}")public List<GarageVehicleResponse>byUser(@PathVariable String username,Authentication auth){return service.byUser(username,auth);}@PostMapping@ResponseStatus(HttpStatus.CREATED)public GarageVehicleResponse create(@Valid@RequestBody GarageVehicleRequest r,Authentication auth){return service.create(r,auth);}@PatchMapping("/{id}")public GarageVehicleResponse update(@PathVariable Long id,@Valid@RequestBody GarageVehicleRequest r,Authentication auth){return service.update(id,r,auth);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable Long id,Authentication auth){service.delete(id,auth);}}
